var e={"ERR-SOV-001":{code:`ERR-SOV-001`,name:`خرق حدود السيادة الإقليمية (Jurisdiction Border Crossing)`,description:`محاولة ناقل أو راكب تنفيذ طلب أو قراءة بيانات خارج نطاق الرقعة السداسية المعتمدة لدولته أو إقليمه الإداري.`,action:`تجميد الحساب تشغيلياً فوراً، وإرسال تنبيه لنظام المراقبة الجغرافية لإعادة معايرة الموقع.`},"ERR-SOV-002":{code:`ERR-SOV-002`,name:`تداخل الصلاحيات الحركية (Role Contamination)`,description:`محاولة حساب مسجل بصيغة "راكب" اختراق بروتوكول "الناقل" لتعديل المسارات أو العبث بالطلبات المجاورة، أو العكس.`,action:`تفعيل الحظر الذاتي وتجريد الحساب من "مستوى التحقق الأول" وتحويله للتدقيق الجنائي.`},"ERR-FIN-101":{code:`ERR-FIN-101`,name:`محاولة حقن عمولة المنصة (Commission Injection Attempt)`,description:`استشعار برمجيات الحافة لأي كود دخل على الحزمة المالية يحاول استقطاع نسبة أو فرض رسوم مخفية خارج نطاق فلسفة "صفرية التكلفة".`,action:`إسقاط المعاملة مالياً بالكامل، وتجميد السعر فوراً، وإدراج الجهة المتسببة في القائمة السوداء للنظام.`},"ERR-FIN-102":{code:`ERR-FIN-102`,name:`عدم استقرار "دينار الأمان" (Secure Dinar Out of Sync)`,description:`حدوث خلل أثناء تفعيل محفظة حماية الركاب الاختيارية، أو عدم تطابق القيمة التقديرية المخزنة في الكاش المحلي مع القيمة الفعلية.`,action:`تجميد الرصيد مؤقتاً لحين حدوث "المصافحة الذرية" التالية وتأكيد سلامة المحفظة محلياً.`},"ERR-MAP-201":{code:`ERR-MAP-201`,name:`النزاع الجغرافي للمسافة (Distance Reference Dispute)`,description:`محاولة أحد الأطراف (الراكب أو الناقل) التلاعب بإحداثيات الموقع الفعلي للتهرب من السعر المجمّد، أو عدم تطابق قراءة نظام التشغيل مع مرجع خرائط جوجل الحتمي.`,action:`فرض قراءة مسافة خرائط جوجل (Google Maps) كمرجع قطعي وحيد، وإلغاء أي تعديل يدوي طرأ على الرحلة.`},"ERR-MAP-202":{code:`ERR-MAP-202`,name:`انفصال الرقعة السداسية (Hexagonal Cell Break)`,description:`خروج الناقل عن تغطية خلايا البث الإعلاني أو النبضي المعتمدة أثناء تفعيل الرحلة، مما يهدد دقة بيانات الملاحة.`,action:`تشغيل خوارزمية التتبع التقريبي المحلي لحين استعادة الاتصال بالخلية السداسية الحاضنة.`},"ERR-ADV-301":{code:`ERR-ADV-301`,name:`تجاوز نطاق الخلية المتضررة (Ad Radius Violation)`,description:`محاولة عرض حملة إعلانية مخصصة لـ "خلايا متضررة" محددة (مثل: قصبة عمان أو لواء الكورة) خارج القطر المكاني المرسوم لها.`,action:`حجب الإعلان فوراً من واجهة الراكب، وإعادة الحصة الإعلانية المستهلكة إلى محفظة المعلن دون اقتطاع.`},"ERR-ADV-302":{code:`ERR-ADV-302`,name:`انتهاك "ميثاق العهد الماسي" (Diamond Covenant Breach)`,description:`رصد نظام الذكاء الاصطناعي لمحتوى ترويجي يخرق شروط جودة المنصة، أو يحاول سحب بيانات غير مصرح بها من أجهزة المستخدمين.`,action:`إطلق "مفتاح الفصل الشامل" الخاص بحساب المعلن، وتجميد كافة حملاته النشطة في نفس اللحظة.`},"ERR-KNL-999":{code:`ERR-KNL-999`,name:`الاستنفار الأمني للصندوق الأسود (Emergency Kill Switch Triggered)`,description:`تفعيل المالك أو النظام التلقائي لمفتاح الفصل الشامل نتيجة رصد هجوم شبكي واسع أو محاولة عبث بالنواة الصلبة للنظام.`,action:`تجميد فوري لكافة الطلبات والرحلات النشطة في الإقليم، وحفظ "اللحظة الصفرية" لجميع الأسعار والمحافِظ لضمان عدم ضياع أي حق مالي، ومنع أي اتصال جديد بالسيرفر لحين صدور أمر قتالي بالإلغاء.`}};export{e as t};